function attention(ic,title,text,action,color=''){return `<div class="attention-item" role="button" tabindex="0" data-action="${action}"><span class="attention-icon ${color}">${icon(ic)}</span><div><strong>${title}</strong><p>${text}</p></div>${icon('chevron-right')}</div>`;}
