    if(quantity!==null){c.quantity=quantity;$(`#recipe-qty-${el.dataset.recipeIndex}`).value=quantity;}
    c.itemUnitId=unit.itemUnitId;c.uomId=unit.id;c.uom=unit.abbreviation||unit.name;c.uomName=unit.name;c.unitFactor=unit.factor;
