function countInputUnit(item){return item.units.find(u=>(u.itemUnitId||u.id)===dialog.units[item.rowId])||preferredUnit(item.units,item.units.find(u=>u.stocktake));}
function renderCount(){const loc=$('#count-location').value,area=$('#count-area').value,q=$('[data-input="count-search"]').value;const rows=activeItems().filter(x=>x.locationId===loc&&(area==='all'||x.areaName===area)&&(!dialog.specific||x.rowId===dialog.specific)&&norm(x.name+' '+x.sku).includes(norm(q)));$('#count-rows').innerHTML=`<div class="table-wrap" style="max-height:350px"><table><thead><tr><th>ITEM / SKU</th><th>LOCATION TOTAL</th><th>UOM</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${e(x.name)}</strong><small>${e(x.sku||"Prep")} · ${e(x.areaName||"No area")}</small></td><td><input class="count-input" type="number" min="0" step="any" placeholder="—" aria-label="Contagem of ${e(x.name)}" value="${e(dialog.quantities[x.rowId]??'')}" data-count="${x.rowId}"></td><td>${`<select data-count-unit="${e(x.rowId)}" aria-label="Count unit for ${e(x.name)}">${prioritizeUnits(x.units.filter(validUnit)).map(u=>`<option value="${e(u.itemUnitId||u.id)}" ${(u.itemUnitId||u.id)===(countInputUnit(x)?.itemUnitId||countInputUnit(x)?.id)?'selected':''}>${e(u.name||u.abbreviation)}</option>`).join('')}</select>`}</td></tr>`).join('')}</tbody></table></div>`;}
async function saveCount(){
  if(!$('#count-form').reportValidity())return;
  const loc=$('#count-location').value;let lines;
  try{lines=Object.entries(dialog.quantities).filter(([,v])=>v!=='').map(([id,v])=>{
    const item=inventoryItems().find(x=>x.rowId===id);if(item?.locationId!==loc)return null;
    const unit=countInputUnit(item);return countEntry(item,v,unit?.itemUnitId||unit?.id);
  }).filter(Boolean);if(!lines.length)throw Error('Enter at least one count.');}
  catch(error){$('#form-error').textContent=error.message;return;}
  local.counts.push({id:crypto.randomUUID(),locationId:loc,date:$('#count-date').value,moment:$('#count-moment').value,createdAt:new Date().toISOString(),lines});
  audit(`Inventory count: ${lines.length} items at ${locationName(loc)}`);
  if(await persist('Inventory count saved.')){state.store=loc;goto('inventory');}
}
