function newInvoice(){invoiceFile=null;openModal("Upload invoice",`<form id="invoice-form"><label class="upload-zone" for="invoice-file">${icon('cloud-upload')}<strong id="upload-name">Choose a PDF or image</strong><small>Saved to private storage · Up to 20 MB</small><input class="hidden" id="invoice-file" type="file" accept="application/pdf,image/png,image/jpeg,image/webp" data-change="invoice-file"></label><div class="form-grid" style="margin-top:22px">${field("Supplier",'invoice-supplier',select('invoice-supplier',options(data.suppliers,'',"Select"),'required'))}${field("Responsible location",'invoice-location',select('invoice-location',options(data.locations,formStore()),'required'))}${field("Invoice number",'invoice-number',input('invoice-number','','text','required'))}${field('Total (USD)','invoice-total',input('invoice-total','','number','min="0" step="0.01" required'))}${field("Issue date",'invoice-date',input('invoice-date',today(),'date','required'))}${field("Due date",'invoice-due',input('invoice-due','','date','required'))}</div><div style="margin-top:18px">${notice("Confirm the location. The printed address may differ from the responsible location. The file will be uploaded to private storage and the invoice will be pending review.",true)}</div><p id="form-error" class="error-text" role="alert"></p></form>`,localFoot('save-invoice',"Save for review"),{kind:'invoice',wide:true});}
async function saveInvoice(){
 if(!$('#invoice-form').reportValidity())return;
 if(!invoiceFile){$('#form-error').textContent="Select a document.";return;}
 const form=$('#invoice-form'),id=form.dataset.invoiceId||crypto.randomUUID();form.dataset.invoiceId=id;
 try{
  if(!form.dataset.recordSaved){await command('batch',{changes:[{action:'invoices',payload:{id,number:$('#invoice-number').value.trim(),supplierId:$('#invoice-supplier').value,locationId:$('#invoice-location').value,total:Number($('#invoice-total').value),date:$('#invoice-date').value,dueDate:$('#invoice-due').value}}]},id);form.dataset.recordSaved='true';}
  const response=await fetch(`/api/invoices/${id}/document`,{method:'PUT',headers:{'Content-Type':invoiceFile.type,'X-File-Name':encodeURIComponent(invoiceFile.name)},body:invoiceFile});const result=await response.json();if(!response.ok)throw Error(result.error);
  await refreshData();closeModal(true);goto('invoices');toast("Invoice and document saved and verified in the database.");
 }catch(error){$('#form-error').textContent=error.message+(form.dataset.recordSaved?" The record was saved. Try again to finish uploading the document.":'');}
}

